-- Apply to a new Supabase project. Admin approval is via trusted SQL editor only.
create table public.profiles(id uuid primary key references auth.users on delete cascade,name text not null check(length(name) between 1 and 100),role text not null check(role in ('passenger','driver')),approved boolean not null default false);
create table public.trips(id uuid primary key default gen_random_uuid(),passenger_id uuid not null references public.profiles,driver_id uuid references public.profiles,pickup text not null check(length(pickup) between 1 and 300),destination text not null check(length(destination) between 1 and 300),vehicle text not null check(vehicle in ('rickshaw','tuktuk')),requested_fare numeric(12,2) not null check(requested_fare>0),agreed_fare numeric(12,2) check(agreed_fare>0),payment text not null check(payment in ('cash','transfer')),status text not null default 'open' check(status in ('open','accepted','started','done','cancelled')),created_at timestamptz not null default now());
create table public.offers(id uuid primary key default gen_random_uuid(),trip_id uuid not null references public.trips on delete cascade,driver_id uuid not null references public.profiles,driver_name text not null,fare numeric(12,2) not null check(fare>0),created_at timestamptz not null default now(),unique(trip_id,driver_id));
alter table public.profiles enable row level security; alter table public.trips enable row level security; alter table public.offers enable row level security;
revoke all on public.profiles,public.trips,public.offers from anon,authenticated;
grant select on public.profiles,public.trips,public.offers to authenticated;
grant insert(id,name,role) on public.profiles to authenticated;
grant insert(passenger_id,pickup,destination,vehicle,requested_fare,payment) on public.trips to authenticated;
create policy profile_self_read on public.profiles for select to authenticated using(id=auth.uid());
create policy profile_self_insert on public.profiles for insert to authenticated with check(id=auth.uid() and not approved);
create policy trip_read on public.trips for select to authenticated using(passenger_id=auth.uid() or driver_id=auth.uid() or (status='open' and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='driver' and p.approved)));
create policy trip_insert on public.trips for insert to authenticated with check(passenger_id=auth.uid() and status='open' and driver_id is null and agreed_fare is null and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='passenger'));
create policy offer_read on public.offers for select to authenticated using(driver_id=auth.uid() or exists(select 1 from public.trips t where t.id=trip_id and t.passenger_id=auth.uid()));
create function public.make_offer(trip uuid,amount numeric) returns void language plpgsql security definer set search_path='' as $$ declare p public.profiles; st text; begin select * into p from public.profiles where id=auth.uid(); if p.id is null or p.role<>'driver' or not p.approved then raise exception 'Driver approval required'; end if; select status into st from public.trips where id=trip for update; if st is distinct from 'open' or amount is null or amount<=0 then raise exception 'Invalid offer'; end if; insert into public.offers(trip_id,driver_id,driver_name,fare) values(trip,p.id,p.name,amount) on conflict(trip_id,driver_id) do update set fare=excluded.fare,created_at=now(); end $$;
create function public.accept_offer(offer uuid) returns void language plpgsql security definer set search_path='' as $$ declare o public.offers; tid uuid; begin select trip_id into tid from public.offers where id=offer; perform 1 from public.trips where id=tid and passenger_id=auth.uid() and status='open' for update; if not found then raise exception 'Trip unavailable'; end if; select * into o from public.offers where id=offer; if not exists(select 1 from public.profiles where id=o.driver_id and approved and role='driver') then raise exception 'Driver unavailable'; end if; update public.trips set status='accepted',driver_id=o.driver_id,agreed_fare=o.fare where id=tid; end $$;
create function public.advance_trip(trip uuid) returns void language plpgsql security definer set search_path='' as $$ begin update public.trips set status=case when status='accepted' then 'started' else 'done' end where id=trip and driver_id=auth.uid() and status in ('accepted','started'); if not found then raise exception 'Invalid transition'; end if; end $$;
create function public.cancel_trip(trip uuid) returns void language plpgsql security definer set search_path='' as $$ begin update public.trips set status='cancelled' where id=trip and passenger_id=auth.uid() and status='open'; if not found then raise exception 'Cannot cancel'; end if; end $$;
revoke execute on function public.make_offer(uuid,numeric),public.accept_offer(uuid),public.advance_trip(uuid),public.cancel_trip(uuid) from public,anon;
grant execute on function public.make_offer(uuid,numeric),public.accept_offer(uuid),public.advance_trip(uuid),public.cancel_trip(uuid) to authenticated;
-- Example admin action (replace UUID): update public.profiles set approved=true where id='...' and role='driver';
